<!-- src/components/NowPlayingView.vue -->
<template>
  <Teleport to="body">
    <Transition name="np-fade">
      <div v-if="visible" class="np-overlay noise-overlay">
        <div class="np-bg" :style="{ backgroundImage: `url(${currentSong?.cover})` }"></div><div class="np-bg-tint"></div><div class="np-glow np-glow-one"></div><div class="np-glow np-glow-two"></div>
        <header class="np-topbar"><div class="np-brand"><span class="np-brand-mark">LN</span><span>NOW PLAYING</span></div><div class="np-context"><span class="context-dot"></span> LuNu offline session</div><button class="np-close" @click="emit('close')" title="Thu nhỏ (Esc)">×</button></header>
        <div class="np-body">
          <div class="np-stage" v-show="!showLyrics"><div class="stage-label"><span>01</span><i></i><span>IMMERSIVE AUDIO</span></div><div class="np-vinyl-shadow"></div><div class="np-vinyl" :class="{ spinning: isPlaying }"><div class="vinyl-lines"></div><img v-if="currentSong" :src="currentSong.cover" class="np-cover" :alt="currentSong.title" /><div class="vinyl-center"><span></span></div></div><div class="stage-eq"><i v-for="n in 16" :key="n" :style="{ animationDelay: `${-n * 75}ms`, height: `${18 + ((n * 19) % 65)}%` }"></i></div></div>
          <div class="np-lyrics-container" v-show="showLyrics" ref="lyricsScrollRef"><div class="lyrics-header"><span>LỜI BÀI HÁT</span><span>{{ lyricsLoading ? 'Đang tải' : lyricsStatusText }}</span></div><div v-if="lyricsLoading" class="lyrics-state"><span class="state-spinner">◌</span><p>Đang đọc lyrics...</p></div><div v-else-if="lyricsMissing" class="lyrics-state"><span class="state-mark">Aa</span><p>Chưa có lời bài hát cho track này.</p><button @click="openLyricsManager">Mở Lyrics Lab <span>→</span></button></div><div v-else class="lyrics-scroll"><template v-if="isSynced && parsedLyrics.length"><p v-for="(line, index) in parsedLyrics" :key="`${line.time}-${index}`" class="lyrics-text" :class="{ active: index === activeLyricIndex, passed: index < activeLyricIndex }" @click="emit('seek', line.time)">{{ line.text }}</p></template><p v-else class="lyrics-text default-lyrics">{{ lyricsContent }}</p></div><div v-if="isSynced && !lyricsLoading" class="lyrics-tools"><span>OFFSET <b>{{ lyricsOffset > 0 ? '+' : '' }}{{ lyricsOffset }}ms</b></span><button @click="stepOffset(-100)">−</button><button @click="stepOffset(100)">＋</button><button @click="resetOffset">RESET</button></div></div>
          <div class="np-meta"><p class="np-kicker">{{ showLyrics ? 'SING ALONG' : 'ĐANG PHÁT' }}</p><h1 class="np-title">{{ currentSong?.title || 'Chưa có nhạc' }}</h1><p class="np-artist">{{ currentSong?.artist || 'Chọn một bài hát để bắt đầu' }}</p></div>
          <div class="np-progress"><span class="np-time">{{ formatTime(currentTime) }}</span><input type="range" class="np-range" min="0" :max="duration || 0" :value="currentTime" @input="emit('seek', Number($event.target.value))" :style="{ '--fill': progressPct + '%' }" /><span class="np-time">{{ formatTime(duration) }}</span></div>
          <div class="np-controls"><button class="np-icon-btn" :class="{ active: showLyrics }" @click="showLyrics = !showLyrics" title="Lời bài hát"><span class="lyrics-icon">Aa</span></button><button class="np-round-btn subtle" :class="{ active: isShuffle }" @click="emit('toggle-shuffle')" title="Phát ngẫu nhiên"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 3h5v5M4 20 21 3M21 16v5h-5M15 15l6 6M4 4l5 5"/></svg></button><button class="np-round-btn" @click="emit('prev')" title="Bài trước"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M6 5h2v14H6zM9 12l10-7v14z"/></svg></button><button class="np-play-btn" @click="emit('toggle-play')"><span v-if="isPlaying">Ⅱ</span><span v-else>▶</span></button><button class="np-round-btn" @click="emit('next')" title="Bài tiếp"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M16 5h2v14h-2zM5 5l10 7-10 7z"/></svg></button><button class="np-round-btn subtle" :class="{ active: repeatMode !== 'off' }" @click="emit('toggle-repeat')" title="Lặp lại"><span v-if="repeatMode === 'one'" class="repeat-one">1</span><svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m17 1 4 4-4 4"/><path d="M3 11V9a4 4 0 0 1 4-4h14M7 23l-4-4 4-4"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg></button></div>
        </div>
      </div>
    </Transition>
  </Teleport>
</template>

<script setup>
import { computed, ref, watch } from 'vue';
import { useLyrics } from '../composables/useLyrics.js';
const props = defineProps({ visible: Boolean, currentSong: Object, isPlaying: Boolean, isShuffle: Boolean, repeatMode: String, currentTime: Number, duration: Number, visualizerData: Array });
const emit = defineEmits(['close', 'toggle-play', 'next', 'prev', 'toggle-shuffle', 'toggle-repeat', 'seek', 'manage-lyrics']);
const showLyrics = ref(false); const lyricsScrollRef = ref(null);
const currentSongRef = computed(() => props.currentSong);
const { content: lyricsContent, lines: parsedLyrics, isSynced, isMissing: lyricsMissing, isLoading: lyricsLoading, statusText: lyricsStatusText, offsetMs: lyricsOffset, stepOffset, resetOffset } = useLyrics(currentSongRef, { allowProvider: false });
const openLyricsManager = () => emit('manage-lyrics');
watch(() => props.visible, (newVal) => { if (!newVal) showLyrics.value = false; });
const activeLyricIndex = computed(() => { if (!parsedLyrics.value.length) return -1; let index = -1; parsedLyrics.value.forEach((line, i) => { if (props.currentTime >= line.time - 0.3) index = i; }); return index; });
watch(activeLyricIndex, (newIdx) => { if (newIdx >= 0 && lyricsScrollRef.value && showLyrics.value) { const activeEl = lyricsScrollRef.value.querySelectorAll('.lyrics-text')[newIdx]; if (activeEl) activeEl.scrollIntoView({ behavior: 'smooth', block: 'center' }); } });
const progressPct = computed(() => props.duration ? (props.currentTime / props.duration) * 100 : 0);
const formatTime = (time) => { if (!time || Number.isNaN(time)) return '0:00'; const m = Math.floor(time / 60); const s = Math.floor(time % 60); return `${m}:${s < 10 ? '0' : ''}${s}`; };
</script>

<style scoped>
