 1; display: flex; flex: 1; flex-direction: column; align-items: center; justify-content: center; gap: 19px; padding: 20px; }.np-stage { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; width: min(440px, 68vw); height: min(440px, 48vh); }.stage-label { display: flex; align-items: center; gap: 9px; margin-bottom: 18px; color: var(--text-faint); font: 9px var(--font-mono); letter-spacing: 1.5px; }.stage-label span:first-child { color: var(--gold); }.stage-label i { width: 26px; height: 1px; background: var(--hairline); }.np-vinyl-shadow { position: absolute; width: 275px; height: 40px; bottom: 23px; border-radius: 50%; background: rgba(0,0,0,.45); filter: blur(24px); }.np-vinyl { position: relative; display: flex; align-items: center; justify-content: center; width: min(330px, 42vh); height: min(330px, 42vh); border: 1px solid rgba(255,255,255,.13); border-radius: 50%; background: radial-gradient(circle, #252b38 0 1.5%, #0a0c12 1.8% 12%, #181c27 12.5% 13%, #090b11 13.5% 24%, #151a25 24.5% 25%, #07090e 25.5% 42%, #131722 42.5% 43%, #080a0f 43.5% 60%, #171c27 60.5% 61%, #080a0f 61.5%); box-shadow: 0 30px 80px rgba(0,0,0,.42), 0 0 0 12px rgba(255,255,255,.018), 0 0 0 13px rgba(255,255,255,.04); }.np-vinyl.spinning { animation: spin 10s linear infinite; }.vinyl-lines { position: absolute; inset: 5%; border: 1px solid rgba(255,255,255,.05); border-radius: 50%; box-shadow: inset 0 0 20px rgba(255,255,255,.04); }.np-cover { width: 44%; height: 44%; border: 3px solid #0a0c11; border-radius: 50%; object-fit: cover; box-shadow: 0 0 0 1px rgba(255,255,255,.16), 0 8px 18px rgba(0,0,0,.38); }.vinyl-center { position: absolute; display: flex; align-items: center; justify-content: center; width: 15px; height: 15px; border: 2px solid rgba(255,255,255,.68); border-radius: 50%; background: var(--gold); }.vinyl-center span { width: 3px; height: 3px; border-radius: 50%; background: #12151d; }.stage-eq { display: flex; align-items: end; justify-content: center; gap: 4px; height: 28px; margin-top: 19px; color: var(--gold); opacity: .68; }.stage-eq i { width: 3px; min-height: 5px; border-radius: 4px; background: currentColor; animation: equalizer 760ms ease-in-out infinite alternate; }.np-lyrics-container { width: min(670px, 90vw); height: min(390px, 47vh); overflow-y: auto; mask-image: linear-gradient(to bottom, transparent, black 14%, black 86%, transparent); -webkit-mask-image: linear-gradient(to bottom, transparent, black 14%, black 86%, transparent); }.np-lyrics-container::-webkit-scrollbar { display: none; }.lyrics-header { display: flex; justify-content: space-between; padding-bottom: 15px; border-bottom: 1px solid var(--hairline-soft); color: var(--text-faint); font: 9px var(--font-mono); letter-spacing: 1.6px; }.lyrics-scroll { padding: 48px 0; text-align: center; }.lyrics-text { padding: 6px 0; color: var(--text-main); font: 500 clamp(19px, 2.2vw, 29px)/1.42 var(--font-display); opacity: .18; transform: scale(.92); transition: opacity .28s var(--ease-out), transform .28s var(--ease-out), color .28s var(--ease-out); }.lyrics-text.active { color: var(--gold-bright); opacity: 1; transform: scale(1.08); text-shadow: 0 0 24px rgba(245,185,122,.21); }.lyrics-text.passed { opacity: .43; transform: scale(.98); }.default-lyrics { opacity: 1; transform: none; white-space: pre-wrap; font-family: var(--font-body); font-size: 14px; }.lyrics-empty { padding-top: 55px; color: var(--text-sub); font-size: 14px; font-style: italic; }.lyrics-state { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 280px; text-align: center; color: var(--text-sub); }.state-spinner, .state-mark { display: flex; align-items: center; justify-content: center; width: 52px; height: 52px; margin-bottom: 15px; border: 1px solid var(--hairline); border-radius: 50%; background: var(--glass); color: var(--gold); font: 600 14px var(--font-display); }.state-spinner { animation: spin 1.2s 