 gap: clamp(13px, 2.2vw, 27px); padding-bottom: max(14px, env(safe-area-inset-bottom)); }.np-icon-btn, .np-round-btn { display: flex; align-items: center; justify-content: center; width: 30px; height: 30px; border: 0; border-radius: 10px; background: transparent; color: var(--text-sub); cursor: pointer; }.np-icon-btn:hover, .np-round-btn:hover, .np-icon-btn.active, .np-round-btn.active { color: var(--gold); background: rgba(245,185,122,.09); }.lyrics-icon { font: 700 11px var(--font-display); }.np-round-btn svg { width: 18px; height: 18px; }.np-round-btn.subtle svg { width: 16px; height: 16px; }.np-play-btn { display: flex; align-items: center; justify-content: center; width: 61px; height: 61px; border: 0; border-radius: 50%; background: linear-gradient(135deg, var(--gold-bright), var(--gold)); color: #171019; box-shadow: 0 10px 30px rgba(245,185,122,.24); cursor: pointer; font-size: 21px; }.np-play-btn:hover { transform: scale(1.07); box-shadow: 0 14px 38px rgba(245,185,122,.4); }.repeat-one { font: 700 11px var(--font-mono); }.np-fade-enter-active, .np-fade-leave-active { transition: opacity .33s var(--ease-out), transform .33s var(--ease-out); }.np-fade-enter-from, .np-fade-leave-to { opacity: 0; transform: translateY(30px) scale(.99); }
